input.newString:
.wx-strip {
  display: block;
  width: 100%;
}

.wx-strip__svg {
  display: block;
  width: 100%;
  height: auto;
}

/* Band colored month slots: the verdict band's own tailwind class sets
   the color, fill picks it up through currentColor, and the 22 percent
   tint keeps the glyph and the curve legible on top. One source of
   band color for the badge and the strip (tailwind.config.js cp). */
.wx-slot {
  fill: currentColor;
  fill-opacity: 0.22;
}

.wx-strip__glyph {
  fill: currentColor;
  font-family: var(--wx-font-body);
  font-size: 13px;
}

.wx-strip__month {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 9.5px;
  letter-spacing: 0.06em;
}

.wx-strip__horizon {
  fill: var(--wx-text-faint);
  font-family: var(--wx-font-display);
  font-size: 10px;
  letter-spacing: 0.06em;
}

.wx-strip__empty {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 11px;
}

.wx-strip__placeholder {
  fill: none;
  stroke: var(--wx-rule);
  stroke-dasharray: 4 4;
}

/* Curve, grounds, and front ---------------------------------------------- */

.wx-zero-line {
  stroke: var(--wx-rule);
  stroke-width: 1;
  stroke-dasharray: 3 5;
}

.wx-history-line {
  fill: none;
  stroke: var(--wx-text-faint);
  stroke-width: 1.5;
}

.wx-history-dot {
  fill: var(--wx-text-faint);
}

.wx-history-legend {
  fill: var(--wx-text-faint);
  font-family: var(--wx-font-display);
  font-size: 9.5px;
  letter-spacing: 0.08em;
}

.wx-projection-line {
  fill: none;
  stroke: var(--wx-parchment);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* The worst case continuation: dashed storm color so it never reads
   as the answer key figure on the solid projection line. */
.wx-continuation-line {
  fill: none;
  stroke: var(--wx-storm);
  stroke-width: 2;
  stroke-dasharray: 7 5;
  stroke-linecap: round;
}

.wx-front {
  stroke-width: 2;
}

.wx-front-active {
  stroke: var(--wx-storm);
  stroke-width: 2.5;
}

.wx-front-idle {
  stroke: var(--wx-rule);
  stroke-dasharray: 4 4;
}

/* Pins ------------------------------------------------------------------- */

.wx-pin-stem {
  stroke: var(--wx-parchment);
  stroke-width: 1.5;
  stroke-dasharray: 3 3;
}

.wx-pin-dot {
  fill: currentColor;
  stroke: var(--wx-grounds);
  stroke-width: 1.5;
}

.wx-pin__label {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  paint-order: stroke;
  stroke: var(--wx-grounds);
  stroke-width: 3px;
  stroke-linejoin: round;
}

.wx-pin__label-faint {
  fill: var(--wx-text-faint);
  font-size: 10px;
  font-weight: 400;
}

.wx-ei-pin {
  fill: var(--wx-storm);
  stroke: var(--wx-grounds);
  stroke-width: 1.5;
}

