.wx-pin-stem {
  stroke: var(--wx-parchment);
  stroke-width: 1.5;
  stroke-dasharray: 3 3;
}

.wx-pin-dot {
  fill: currentColor;
  stroke: var(--wx-grounds);
  stroke-width: 1.5;
}

.wx-pin__label {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  paint-order: stroke;
  stroke: var(--wx-grounds);
  stroke-width: 3px;
  stroke-linejoin: round;
}

.wx-pin__label-faint {
  fill: var(--wx-text-faint);
  font-size: 10px;
  font-weight: 400;
}

.wx-ei-pin {
  fill: var(--wx-storm);
  stroke: var(--wx-grounds);
  stroke-width: 1.5;
}

