input.newString:
/* ==========================================================================
   Condition bands: the sky legend with the printed threshold sentence.
   One band vocabulary (src/lib/verdict.ts): the band's tailwind class on
   the list item sets the color, currentColor carries it into the left
   rule and the label, and the responsive grid keeps five bands readable
   from a phone up to a judging table.
   ========================================================================== */

.wx-bands {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.wx-band {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 8px 12px;
  background: rgba(233, 224, 201, 0.05);
  border: 1px solid var(--wx-rule);
  border-left: 6px solid currentColor;
  border-radius: var(--wx-radius);
  min-height: 44px;
}

.wx-band-active {
  box-shadow: inset 0 0 0 2px var(--wx-parchment);
}

.wx-band__glyph {
  font-size: 1rem;
  color: var(--wx-parchment);
}

.wx-band__body {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  min-width: 0;
}

.wx-band__label {
  font-family: var(--wx-font-display);
  font-size: 0.8125rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: currentColor;
}

.wx-band__threshold {
  font-family: var(--wx-font-body);
  font-size: 0.8125rem;
  color: var(--wx-text-dim);
}

