input.newString:
/* ==========================================================================
   EI cliff overlay: a marker line that sits over the forecast strip, plus
   a dotted second line for the worst case pin. The wiring view wraps the
   strip and this overlay in .wx-cliff-wrap, which is the positioning
   context; the overlay's own .wx-cliff-set fills that box and the lines
    position against it with the slot percent the strip's stripLayout
    shares, so the marker lands on the same x the curve uses.
   ========================================================================== */

.wx-cliff-wrap {
  position: relative;
}

.wx-cliff-set {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.wx-cliff {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 0;
  border-left: 2px dashed var(--wx-storm);
}

/* The worst case continuation line: dotted and dimmer, so it never
   reads as the answer key marker or the solid projection curve. */
.wx-cliff-after {
  border-left-style: dotted;
  opacity: 0.7;
}

.wx-cliff__label {
  position: absolute;
  top: 3px;
  left: 0;
  white-space: nowrap;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--wx-storm);
  color: var(--wx-grounds);
  font-family: var(--wx-font-display);
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* On a phone the label is wider than the gap to the strip edge, so it
   wraps instead of overflowing the panel. */
@media (max-width: 40rem) {
  .wx-cliff__label {
    white-space: normal;
    max-width: 62vw;
  }
}

